import sys

MOD = 998244353
factorials = []
invFactorials = []

def prepareFactorials():
    global factorials, invFactorials
    factorials = [1] * 200001
    invFactorials = [1] * 200001
    for i in range(1, 200001):
        factorials[i] = (factorials[i-1] * i) % MOD
    invFactorials[200000] = pow(factorials[200000], MOD - 2, MOD)
    for i in range(199999, 0, -1):
        invFactorials[i] = (invFactorials[i+1] * (i+1)) % MOD

def ncr(n, r):
    if r > n or r < 0:
        return 0
    return (factorials[n] * invFactorials[r] % MOD) * invFactorials[n - r] % MOD

def powMod(base, exp, mod):
    res = 1
    while exp > 0:
        if exp & 1:
            res = (res * base) % mod
        base = (base * base) % mod
        exp >>= 1
    return res

def main():
    prepareFactorials()
    input_data = sys.stdin.read().strip().split()
    n = int(input_data[0])
    k = int(input_data[1])
    if k > n:
        print(0)
        return
    diff = n - k
    totalSum = 0
    for i in range(diff + 1):
        term = (ncr(diff, i) * powMod(diff - i, n, MOD)) % MOD
        if i % 2 == 0:
            totalSum += term
        else:
            totalSum -= term
        totalSum %= MOD
    result = (totalSum * ncr(n, diff)) % MOD
    if diff == 0:
        print(result)
    else:
        print((2 * result) % MOD)

if __name__ == "__main__":
    main()

